import React, { useEffect } from 'react';
import { Toaster, toast } from 'sonner';
import Header from './components/Header';
import Hero from './components/Hero';
import About from './components/About';
import Experience from './components/Experience';
import Projects from './components/Projects';
import Testimonials from './components/Testimonials';
import Contact from './components/Contact';
import { LanguageProvider } from './context/LanguageContext';

function App() {

  useEffect(() => {
    // Determine greeting based on time
    const getGreeting = () => {
      const hour = new Date().getHours();
      if (hour >= 5 && hour < 12) return "Bom dia";
      if (hour >= 12 && hour < 18) return "Boa tarde";
      return "Boa noite";
    };

    // Simulate a quick load to use the 'promise' variant as requested
    const loadPortfolio = () => new Promise((resolve) => setTimeout(resolve, 1500));

    toast.promise(loadPortfolio, {
      loading: 'Carregando experiência...',
      success: `${getGreeting()}! Seja bem vindo!`,
      error: 'Erro',
      style: {
        backgroundColor: '#0A0A0A',
        color: '#FACC15', // Brand Yellow
        borderColor: 'rgba(250, 204, 21, 0.3)',
        borderWidth: '1px'
      }
    });
  }, []);

  return (
    <LanguageProvider>
      <div className="bg-brand-dark min-h-screen text-neutral-50 selection:bg-brand-yellow selection:text-brand-dark">
        <Toaster position="top-center" theme="dark" />
        <Header />
        <main>
          <Hero />
          <About />
          <Experience />
          <Projects />
          <Testimonials />
          <Contact />
        </main>
      </div>
    </LanguageProvider>
  );
}

export default App;

