                <span className="text-neutral-500 text-sm">{t.projects.modal.confidential}</span>
                <Button onClick={(e) => {e.stopPropagation(); setSelectedProject(null)}} variant="outline" className="text-xs px-4 py-2">
                  {t.projects.modal.close}
                </Button>
              </div>

            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </section>
  );
};

